WITH fixes(pos,why) AS (VALUES (9,'Correto. O art. 5º, X, da Constituição protege a intimidade, a vida privada, a honra e a imagem. A violação pode gerar reparação por dano material ou moral.'),(10,'Correto. O art. 5º, X, da Constituição garante indenização por dano material ou moral decorrente da violação da intimidade, vida privada, honra ou imagem.'),(11,'Correto. O art. 5º, XII, da Constituição protege o sigilo da correspondência e das comunicações, inclusive de dados, com as distinções e ressalvas constitucionais.'),(13,'Correto. A EC 115/2022 inseriu no art. 5º, LXXIX, da Constituição o direito fundamental à proteção de dados pessoais, inclusive nos meios digitais.'),(14,'Correto. O art. 21, XXVI, da Constituição atribui à União organizar e fiscalizar a proteção e o tratamento de dados pessoais, nos termos da lei.'),(15,'Correto. O art. 22, XXX, da Constituição reserva à União a competência privativa para legislar sobre proteção e tratamento de dados pessoais.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.pos=e.ordinality WHERE sm.slug='constitucional-privacidade-dados' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;